const fs = require('fs');
const path = require('path');

const root = process.cwd();
const indexPath = path.join(root, 'backend/index.ts');
let source = fs.readFileSync(indexPath, 'utf8');

function removeBetween(start, end) {
  const a = source.indexOf(start);
  if (a < 0) return false;
  const b = source.indexOf(end, a);
  if (b < 0) throw new Error(`Cleanup marker not found: ${end}`);
  source = source.slice(0, a) + source.slice(b);
  return true;
}

// Remove the old provider/model configuration and the entire old chat/agent implementation.
removeBetween('const AI_MODELS = [', 'const BACKTEST_MAX_TICKS');
removeBetween('const OPENAI_SYSTEM_INSTRUCTION = `', 'type StrategySpec');

// The remaining research/data code still uses this limit name; keep the same safe bound without the old AI alias.
source = source.replace(/SIRE_MAX_ANALYSIS_TICKS/g, 'BACKTEST_MAX_TICKS');
source = source.replace(/SIRE_MAX_TICKS/g, 'BACKTEST_MAX_TICKS');
source = source.replace(/SIRE_MAX_STEPS/g, '18');

// Remove only provider/chat routes. The /gpt data/research endpoints are retained because they are
// SIRE's provider-neutral research/data gateway, not an external model integration.
const routes = [
  '/api/sire/agent/chat',
  '/api/sire/openai/chat',
  '/api/sire/gpt/manifest',
  '/api/sire/gpt/tool',
];
for (const route of routes) {
  const escaped = route.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&');
  const re = new RegExp(`\\n  '(?:GET|POST) ${escaped}': \\[\\s\\S]*?\\n  \\],`, 'g');
  source = source.replace(re, '');
}

fs.writeFileSync(indexPath, source.replace(/\n{3,}/g, '\n\n'));

const deleteFiles = [
  'backend/openrouter-team.ts',
  'backend/openrouter-env.mjs',
  'backend/openrouter-native-fetch.mjs',
  '.github/workflows/fix-ai-model-routing.yml',
  '.github/workflows/fix-nvidia-request.yml',
  '.github/workflows/fix-sire-tool-calling.yml',
  '.github/workflows/upgrade-sire-intelligence.yml',
];
for (const rel of deleteFiles) {
  const file = path.join(root, rel);
  if (fs.existsSync(file)) fs.rmSync(file);
}

// Remove legacy provider references from dependency manifests without touching unrelated packages.
for (const rel of ['package.json', 'package-lock.json']) {
  const file = path.join(root, rel);
  if (!fs.existsSync(file)) continue;
  let text = fs.readFileSync(file, 'utf8');
  if (rel === 'package.json') {
    const pkg = JSON.parse(text);
    for (const section of ['dependencies', 'devDependencies', 'optionalDependencies']) {
      if (!pkg[section]) continue;
      for (const name of Object.keys(pkg[section])) {
        if (/openrouter|openai|@google\/generative|gemini|nvidia|bazaar/i.test(name)) delete pkg[section][name];
      }
    }
    fs.writeFileSync(file, JSON.stringify(pkg, null, 2) + '\n');
  } else {
    // package-lock is regenerated by npm; do not perform unsafe line deletion here.
  }
}

// Remove temporary cleanup workflows themselves.
for (const rel of ['.github/workflows/cleanup-legacy-ai.yml', '.github/workflows/cleanup-ai-v2.yml']) {
  const file = path.join(root, rel);
  if (fs.existsSync(file)) fs.rmSync(file);
}

console.log('Legacy AI cleanup edits applied.');
